import { NavLink, useNavigate } from 'react-router-dom'
import { useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'
import { Sun, CalendarDays, Plus, Wallet, MoreHorizontal, Clock, ChartNoAxesCombined, UserRound, X,
  DollarSign, FileText, Camera, Mic, BookOpen } from 'lucide-react'
import { useAppState } from '../../context/appHooks'
import { useMediaQuery, useLocalPref } from '../../ui/hooks'

const TABS = [
  { to: '/', label: 'Today', icon: Sun },
  { to: '/plan', label: 'Plan', icon: CalendarDays },
  null, // capture button
  { to: '/money', label: 'Money', icon: Wallet },
  { to: '/more', label: 'More', icon: MoreHorizontal },
]

const CAPTURE_ITEMS = [
  { key: 'expense', label: 'Expense', icon: DollarSign, color: '#10B981', route: '/capture?type=expense' },
  { key: 'time', label: 'Time log', icon: Clock, color: '#22D3EE', route: '/capture?type=time' },
  { key: 'diary', label: 'Diary plan', icon: BookOpen, color: '#6366F1', route: '/capture?type=diary' },
  { key: 'note', label: 'Quick note', icon: FileText, color: '#8B5CF6', route: '/capture?type=note' },
]

export default function BottomNav() {
  const isDesktop = useMediaQuery('(min-width: 901px)')
  const navigate = useNavigate()
  const [captureOpen, setCaptureOpen] = useState(false)

  if (isDesktop) return null

  return <>
    {/* Capture popover */}
    <AnimatePresence>
      {captureOpen && <>
        <motion.div
          initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
          style={{ position: 'fixed', inset: 0, background: 'rgba(3,6,15,.5)', backdropFilter: 'blur(4px)', zIndex: 1200 }}
          onClick={() => setCaptureOpen(false)} />
        <motion.div
          initial={{ y: 60, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 60, opacity: 0 }}
          transition={{ type: 'spring', stiffness: 400, damping: 30 }}
          style={{
            position: 'fixed', bottom: 'calc(68px + env(safe-area-inset-bottom) + 12px)', left: '50%', transform: 'translateX(-50%)',
            background: 'var(--card)', border: '1px solid var(--line-strong)', borderRadius: 20,
            padding: '1rem', display: 'flex', gap: 12, zIndex: 1201,
            boxShadow: '0 -8px 40px rgba(0,0,0,.35)',
          }}>
          {CAPTURE_ITEMS.map(item => <button key={item.key} type="button"
            onClick={() => { setCaptureOpen(false); navigate(item.route) }}
            style={{
              display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6,
              border: 0, background: 'transparent', color: 'var(--text-2)',
              fontSize: '.72rem', fontWeight: 650, cursor: 'pointer', padding: '.5rem .7rem', borderRadius: 12,
              minWidth: 64,
            }}>
            <span style={{ width: 44, height: 44, borderRadius: 14, background: `color-mix(in srgb, ${item.color} 18%, transparent)`, display: 'grid', placeItems: 'center' }}>
              <item.icon size={20} style={{ color: item.color }} />
            </span>
            {item.label}
          </button>)}
        </motion.div>
      </>}
    </AnimatePresence>

    {/* Bottom bar */}
    <nav className="life-bottom-nav" aria-label="Main navigation" style={{
      position: 'fixed', bottom: 0, left: 0, right: 0, zIndex: 1100,
      display: 'flex', justifyContent: 'space-around', alignItems: 'flex-start',
      background: 'linear-gradient(180deg, var(--card-2), var(--card))',
      borderTop: '1px solid var(--line)',
      paddingBottom: 'env(safe-area-inset-bottom)',
      backdropFilter: 'blur(16px) saturate(180%)',
      WebkitBackdropFilter: 'blur(16px) saturate(180%)',
      height: 68,
    }}>
      {TABS.map((tab, i) => {
        if (!tab) {
          // Center capture button
          return <button key="capture" type="button" className="bottom-capture" aria-label="Capture something"
            onClick={() => setCaptureOpen(o => !o)}
            style={{
              width: 52, height: 52, borderRadius: 16, border: 0,
              background: captureOpen ? 'rgba(244,63,94,.2)' : 'linear-gradient(135deg, #6366F1, #8B5CF6)',
              color: captureOpen ? '#F43F5E' : '#fff',
              display: 'grid', placeItems: 'center', cursor: 'pointer',
              marginTop: -6,
              boxShadow: captureOpen ? 'none' : '0 8px 22px -6px rgba(99,102,241,.6)',
              transition: 'all .2s var(--ease-spring)',
            }}>
            {captureOpen ? <X size={24} /> : <Plus size={24} />}
          </button>
        }
        return <NavLink key={tab.to} to={tab.to} end={tab.to === '/'}
          tabIndex={0} aria-current={window.location.pathname === tab.to ? 'page' : undefined}
          style={({ isActive }) => ({
            display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2,
            padding: '.6rem .5rem .3rem', textDecoration: 'none', minWidth: 56,
            color: isActive ? 'var(--accent)' : 'var(--text-3)',
            fontSize: '.65rem', fontWeight: isActive ? 700 : 600,
            transition: 'color .15s',
          })}>
          <tab.icon size={22} />
          <span>{tab.label}</span>
        </NavLink>
      })}
    </nav>
  </>
}

/**
 * Diary ΓåÆ plan tasks. Deterministic Hinglish / Hindi / English parser (plan ┬º6.3, ┬º20.3).
 *
 * Bare hours ("9 se 11", "7 baje") are resolved with the waking-window rule: keep only the AM/PM
 * readings whose whole interval fits inside the user's wakeΓÇôsleep window. If more than one fits,
 * earlier diary lines give sequence context (a diary is written in order); if there is still no
 * single answer, the task carries a warning with both options so the UI can resolve it in one tap.
 */
const uid = (prefix = 'record') => `${prefix}_${globalThis.crypto.randomUUID()}`
const pad = n => String(n).padStart(2, '0')
export const minuteClock = minutes => `${pad(Math.floor(minutes / 60) % 24)}:${pad(minutes % 60)}`
const clockToMinutes = clock => { const m = /^(\d{1,2}):(\d{2})$/.exec(clock || ''); return m ? Number(m[1]) * 60 + Number(m[2]) : null }
const label12 = minutes => { const h = Math.floor(minutes / 60) % 24, m = minutes % 60; return `${h % 12 || 12}:${pad(m)} ${h < 12 ? 'AM' : 'PM'}` }

const DEVANAGARI = 'αÑªαÑºαÑ¿αÑ⌐αÑ¬αÑ½αÑ¼αÑ¡αÑ«αÑ»'
const MORNING = /\b(subah|subha|savere|morning|am)\b|αñ╕αÑüαñ¼αñ╣|αñ╕αñ╡αÑçαñ░αÑç/i
const AFTERNOON = /\b(dopahar|dopehar|dupahar|afternoon|noon)\b|αñªαÑïαñ¬αñ╣αñ░/i
const EVENING = /\b(shaam|sham|evening)\b|αñ╢αñ╛αñ«/i
const NIGHT = /\b(raat|rat|night|tonight)\b|αñ░αñ╛αññ/i
// Semantic hints help when only the activity says when it happens ("paune 8 nashta").
const HINT_AM = /\b(nashta|breakfast|uth(na|ega|unga|o)?|wake|jog(ging)?|morning walk)\b|αñ¿αñ╛αñ╢αÑìαññαñ╛|αñëαñáαñ¿αñ╛/i
const HINT_NOON = /\b(lunch)\b|αñ▓αñéαñÜ/i
const HINT_PM = /\b(dinner|sona|sleep|bed)\b|αñíαñ┐αñ¿αñ░|αñ╕αÑïαñ¿αñ╛/i

export const CATEGORY_RULES = [
  ['Study', /\b(study|studies|padh(ai|na|unga)?|read(ing)?|gate|revision|revise|lecture|course|notes|thermo|maths?|physics|chem(istry)?|exam|practice|mock|dsa|leetcode)\b|αñ¬αñóαñ╝|αñ¬αñóαñ╛αñê|αñ¬αñóαñ╝αñ╛αñê/i],
  ['Exercise', /\b(gym|walk|run(ning)?|jog(ging)?|yoga|exercise|workout|swim|cycle|cycling|stretch|sport|cricket|football|badminton)\b|αñ╡αÑìαñ»αñ╛αñ»αñ╛αñ«|αñÜαñ▓αñ¿αñ╛|αñ»αÑïαñù/i],
  ['Meals', /\b(lunch|dinner|breakfast|nashta|khana|meal|eat|snack|chai)\b|αñûαñ╛αñ¿αñ╛|αñ¿αñ╛αñ╢αÑìαññαñ╛/i],
  ['Sleep', /\b(sleep|sona|nap|bed)\b|αñ╕αÑïαñ¿αñ╛|αñ¿αÑÇαñéαñª/i],
  ['Morning Routine', /\b(uth(na)?|wake|bath|nahana|brush|ready|freshen)\b|αñëαñáαñ¿αñ╛|αñ¿αñ╣αñ╛αñ¿αñ╛/i],
  ['Travel', /\b(travel|commute|metro|bus|drive|cab|train|flight|office jana)\b/i],
  ['Entertainment', /\b(movie|netflix|series|game|gaming|youtube|music|show)\b/i],
  ['Self-Care', /\b(meditat(e|ion)|journal|skincare|therapy|self[- ]care|rest)\b|αñºαÑìαñ»αñ╛αñ¿/i],
  ['Deep Work', /\b(office|work|project|meeting|standup|stand-up|email|emails|code|coding|client|call|review|design|report)\b/i],
]
export function guessCategory(text) { return CATEGORY_RULES.find(([, re]) => re.test(text))?.[0] || 'Deep Work' }

/** Normalise Hindi words for quarter/half hours and Devanagari digits into clock tokens. */
export function normaliseDiaryLine(raw) {
  let line = String(raw).replace(/[αÑª-αÑ»]/g, d => String(DEVANAGARI.indexOf(d)))
  line = line.replace(/^[\s\-*ΓÇó┬╖>~ΓÇôΓÇöΓ£àΓÿæ∩╕ÅΓ£ö∩╕Å≡ƒö╣≡ƒö╕Γû¬∩╕ÅΓû½∩╕ÅΓ¡É∩╕Å≡ƒæëΓ₧í∩╕Å\u2022\u25CF\u25E6\u2023\u2043]+/u, '')
  line = line.replace(/\b(saade|sade|saadhe)\s+(\d{1,2})\b|αñ╕αñ╛αñóαñ╝αÑç\s*(\d{1,2})/gi, (_, _w, h, h2) => `${Number(h ?? h2)}:30`)
  line = line.replace(/\b(sava|sawa)\s+(\d{1,2})\b|αñ╕αñ╡αñ╛\s*(\d{1,2})/gi, (_, _w, h, h2) => `${Number(h ?? h2)}:15`)
  line = line.replace(/\b(paune|pone)\s+(\d{1,2})\b|αñ¬αÑîαñ¿αÑç\s*(\d{1,2})/gi, (_, _w, h, h2) => { const hour = Number(h ?? h2); return `${hour === 1 ? 12 : hour - 1}:45` })
  line = line.replace(/\bdhai\b|αñóαñ╛αñê/gi, '2:30').replace(/\bderh\b|αñíαÑçαñóαñ╝/gi, '1:30')
  line = line.replace(/\bhalf past\s+(\d{1,2})\b/gi, (_, h) => `${h}:30`).replace(/\bquarter past\s+(\d{1,2})\b/gi, (_, h) => `${h}:15`)
  return line
}

/** Split one physical line into several tasks when commas separate time-led phrases. */
export function splitDiary(text) {
  return String(text).split(/\n|;/).map(l => l.trim()).filter(Boolean)
    .flatMap(line => line.split(/,(?=\s*(?:\d|saade|sade|sava|sawa|paune|subah|shaam|sham|raat|dopahar|[αÑª-αÑ»]))/i).map(s => s.trim()).filter(Boolean))
}

const TOKEN = String.raw`(\d{1,2})(?::([0-5]\d))?(?:\s*(am|pm|a\.m\.|p\.m\.)(?![a-z]))?`
const RANGE = new RegExp(String.raw`(?:^|[^\d:])${TOKEN}\s*(?:baje|αñ¼αñ£αÑç|bje)?\s*(?:[-ΓÇôΓÇö]|\bto\b|\bse\b|αñ╕αÑç|\btill\b|\buntil\b)\s*${TOKEN}(?![\d:])`, 'i')
const POINT_COLON = /(?:^|[^\d:])(\d{1,2}):([0-5]\d)\s*(am|pm)?(?![\d:])/i
const POINT_AMPM = /(?:^|[^\d:])(\d{1,2})\s*(am|pm)\b/i
const POINT_BAJE = /(?:^|[^\d:])(\d{1,2})\s*(?:baje|αñ¼αñ£αÑç|bje)\b/i
const DURATION = /(\d+(?:\.\d+)?)\s*(hours?|hrs?|h|αñÿαñéαñƒαÑç?|αñÿαñéαñƒαñ╛|ghante?|ghanta|minutes?|mins?|m|αñ«αñ┐αñ¿αñƒ)(?=\s|$|[,.;)])/i

/** Candidate minute-of-day readings for a token. */
function readings({ hour, minute, period, raw }, context) {
  if (hour > 23 || minute > 59) return []
  const p = (period || '').replace(/\./g, '').toLowerCase()
  if (p) { if (hour < 1 || hour > 12) return []; return [(hour % 12 + (p === 'pm' ? 12 : 0)) * 60 + minute] }
  if (hour >= 13 || hour === 0 || /^0\d/.test(raw)) return [hour * 60 + minute] // explicit 24-hour
  if (context === 'am') return [(hour % 12) * 60 + minute]
  if (context === 'noon') return [(hour === 12 ? 12 : hour < 6 ? hour + 12 : hour) * 60 + minute]
  if (context === 'pm') return [(hour % 12 + 12) * 60 + minute]
  if (context === 'night') return [(hour === 12 || hour <= 4 ? hour % 12 : hour % 12 + 12) * 60 + minute]
  return [...new Set([(hour % 12) * 60 + minute, (hour % 12 + 12) * 60 + minute])]
}

function contextOf(line) {
  if (MORNING.test(line)) return 'am'
  if (AFTERNOON.test(line)) return 'noon'
  if (EVENING.test(line)) return 'pm'
  if (NIGHT.test(line)) return 'night'
  if (HINT_AM.test(line)) return 'am'
  if (HINT_NOON.test(line)) return 'noon'
  if (HINT_PM.test(line)) return 'pm'
  return ''
}

/** Does [start, start+duration) sit inside the waking window (which may itself wrap midnight)? */
function insideWindow(start, duration, wake, sleep) {
  const end = start + duration
  if (sleep > wake) return start >= wake && end <= sleep
  // Window wraps past midnight (e.g. wake 07:00, sleep 01:00).
  const s = start < wake ? start + 1440 : start
  return s >= wake && s + duration <= sleep + 1440
}

function cleanTitle(line) {
  const cleaned = line
    .replace(RANGE, ' ').replace(POINT_COLON, ' ').replace(POINT_AMPM, ' ').replace(POINT_BAJE, ' ').replace(DURATION, ' ')
    .replace(/\b\d{4}-\d{2}-\d{2}\b/g, ' ')
    .replace(/\b(must|should|could|zaroori|jaruri|important|baje|tak|se|subah|shaam|sham|raat|dopahar|dopehar|morning|evening|night|afternoon|at|from)\b|αñ£αñ╝αñ░αÑéαñ░αÑÇ|αñ£αñ░αÑéαñ░αÑÇ|αñ¼αñ£αÑç|αññαñò|αñ╕αÑüαñ¼αñ╣|αñ╢αñ╛αñ«|αñ░αñ╛αññ|αñªαÑïαñ¬αñ╣αñ░/gi, ' ')
    .replace(/[(),:ΓÇôΓÇö-]+/g, ' ').replace(/\s{2,}/g, ' ').trim()
  return cleaned || line.trim()
}

/**
 * @param {string} text diary text
 * @param {{wakeTime?:string, sleepTime?:string}} options waking window (defaults 06:00ΓÇô22:30)
 */
export function parseDiary(text, options = {}) {
  const wake = clockToMinutes(options.wakeTime) ?? 6 * 60
  const sleep = clockToMinutes(options.sleepTime) ?? 22 * 60 + 30
  let previousStart = null
  return splitDiary(text).map(rawLine => {
    const line = normaliseDiaryLine(rawLine)
    const context = contextOf(line)
    const clockText = line.replace(/\b\d{4}-\d{2}-\d{2}\b/g, '')
    const duration = line.match(DURATION)
    const durationMinutes = duration ? Math.round(Number(duration[1]) * (/^(h|αñÿαñé|gh)/i.test(duration[2]) ? 60 : 1)) : null
    let startTime = '', estimateMinutes = durationMinutes ?? 30, warning = '', endsNextDay = false, periodInferred = false, ambiguity = null
    const range = clockText.match(RANGE)
    const colon = !range && clockText.match(POINT_COLON)
    const ampm = !range && !colon && clockText.match(POINT_AMPM)
    const baje = !range && !colon && !ampm && clockText.match(POINT_BAJE)
    const point = colon || ampm || baje
    if (range) {
      const a = { hour: Number(range[1]), minute: Number(range[2] || 0), period: range[3], raw: range[1] }
      const b = { hour: Number(range[4]), minute: Number(range[5] || 0), period: range[6], raw: range[4] }
      // A period on one side applies to an unmarked other side ("9-11am").
      if (!a.period && b.period && a.hour <= b.hour) a.period = b.period
      if (!b.period && a.period && b.hour >= a.hour && b.hour !== 12) b.period = a.period
      const pairs = []
      for (const s of readings(a, context)) for (const e of readings(b, context)) {
        const span = (e - s + 1440) % 1440
        if (span > 0 && span <= 12 * 60) pairs.push({ start: s, span })
      }
      const unique = [...new Map(pairs.map(p => [`${p.start}-${p.span}`, p])).values()]
      let fit = unique.length > 1 ? unique.filter(p => insideWindow(p.start, p.span, wake, sleep)) : unique
      if (fit.length > 1 && previousStart != null) {
        const after = fit.filter(p => p.start >= previousStart).sort((x, y) => x.start - y.start)
        if (after.length) { fit = [after[0]]; periodInferred = true }
      }
      if (fit.length === 1) {
        startTime = minuteClock(fit[0].start); estimateMinutes = fit[0].span; endsNextDay = fit[0].start + fit[0].span >= 1440
      } else if (fit.length > 1 || unique.length > 1) {
        const options = (fit.length ? fit : unique).slice(0, 2)
        warning = `ΓÇ£${range[0].trim()}ΓÇ¥ ΓÇö AM/PM? Choose one before approving.`
        ambiguity = { options: options.map(p => ({ label: `${label12(p.start)} ΓÇô ${label12((p.start + p.span) % 1440)}`, startTime: minuteClock(p.start), estimateMinutes: p.span, endsNextDay: p.start + p.span >= 1440 })) }
        estimateMinutes = options[0].span
      } else warning = 'This range is ambiguous. Specify AM/PM for both ends or edit its duration.'
    } else if (point) {
      const token = colon ? { hour: Number(colon[1]), minute: Number(colon[2]), period: colon[3], raw: colon[1] }
        : ampm ? { hour: Number(ampm[1]), minute: 0, period: ampm[2], raw: ampm[1] }
        : { hour: Number(baje[1]), minute: 0, period: '', raw: baje[1] }
      const all = readings(token, context)
      let fit = all.length > 1 ? all.filter(s => insideWindow(s, estimateMinutes, wake, sleep)) : all
      if (fit.length > 1 && previousStart != null) {
        const after = fit.filter(s => s >= previousStart).sort((x, y) => x - y)
        if (after.length) { fit = [after[0]]; periodInferred = true }
      }
      if (fit.length === 1) { startTime = minuteClock(fit[0]); endsNextDay = fit[0] + estimateMinutes > 1440 }
      else {
        const options = (fit.length ? fit : all).slice(0, 2)
        warning = `ΓÇ£${point[0].trim()}ΓÇ¥ ΓÇö AM/PM? Choose one before approving.`
        ambiguity = { options: options.map(s => ({ label: label12(s), startTime: minuteClock(s), estimateMinutes, endsNextDay: false })) }
      }
    }
    if (startTime) previousStart = clockToMinutes(startTime)
    const priority = /\bmust\b|zaroori|jaruri|αñ£αñ╝αñ░αÑéαñ░αÑÇ|αñ£αñ░αÑéαñ░αÑÇ|\bimportant\b|!{2,}/i.test(line) ? 'must' : /\bcould\b|\bmaybe\b|agar time/i.test(line) ? 'could' : 'should'
    return {
      id: uid('block'), taskId: uid('task'), title: cleanTitle(line), rawLine: rawLine.trim(),
      estimateMinutes, originalEstimateMinutes: estimateMinutes, estimateAssumed: durationMinutes == null && !range,
      startTime, endsNextDay, reminderMinutes: 10, priority, fixed: Boolean(startTime),
      category: guessCategory(line), completionCriterion: '', explicitDate: line.match(/\b\d{4}-\d{2}-\d{2}\b/)?.[0] || '',
      warning, ambiguity, periodInferred, source: 'diary-draft',
    }
  })
}

/** Apply one of the ambiguity options to a parsed task (UI one-tap resolve). */
export function resolveAmbiguity(task, option) {
  return { ...task, startTime: option.startTime, estimateMinutes: option.estimateMinutes, originalEstimateMinutes: task.originalEstimateMinutes ?? option.estimateMinutes, endsNextDay: Boolean(option.endsNextDay), fixed: true, warning: '', ambiguity: null }
}

/** Auto-suggested implementation intention for a Must block (plan ┬º12.1). */
export function suggestIntention(block) {
  if (!block?.startTime) return ''
  const first = { Study: 'open my notes and start the first problem', Exercise: 'put on my shoes and start the warm-up', 'Deep Work': 'close chats and open the main file', Meals: 'step away from the screen', Sleep: 'put the phone away and switch off the lights' }[block.category] || `start ΓÇ£${block.title}ΓÇ¥`
  return `If it's ${block.startTime}, then I ${first}.`
}

import { useState, useRef, useEffect } from 'react'
import { Sparkles, Send } from 'lucide-react'
import { Page, Card, Button, Field, EmptyState } from '../ui/index'
import { useAppState, useAppActions } from '../context/appHooks'

export default function AskLifeOS() {
  const state = useAppState()
  const { patchModule } = useAppActions()
  const [input, setInput] = useState('')
  const [loading, setLoading] = useState(false)
  const chatEndRef = useRef(null)

  const messages = state.ai?.chatHistory || state.aiChat?.messages || []

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages, loading])

  const handleSend = () => {
    const text = input.trim()
    if (!text || loading) return

    const userMsg = {
      id: crypto.randomUUID(),
      role: 'user',
      content: text,
      createdAt: new Date().toISOString()
    }

    const newMessages = [...messages, userMsg]

    // Save user message immediately
    if (state.ai) {
      patchModule('ai', { chatHistory: newMessages })
    } else {
      patchModule('aiChat', { messages: newMessages })
    }

    setInput('')
    setLoading(true)

    // Mock response
    setTimeout(() => {
      const aiMsg = {
        id: crypto.randomUUID(),
        role: 'assistant',
        content: 'I am your LifeOS assistant. The AI backend is not yet fully connected.',
        createdAt: new Date().toISOString()
      }

      const finalMessages = [...newMessages, aiMsg]
      if (state.ai) {
        patchModule('ai', { chatHistory: finalMessages })
      } else {
        patchModule('aiChat', { messages: finalMessages })
      }
      setLoading(false)
    }, 800)
  }

  return (
    <Page title="Ask LifeOS" icon={Sparkles}>
      <Card
        style={{
          display: 'flex',
          flexDirection: 'column',
          height: 'min(800px, calc(100vh - 180px))'
        }}
      >
        <div style={{ flex: 1, overflowY: 'auto', padding: '16px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {messages.length === 0 ? (
            <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <EmptyState
                icon={Sparkles}
                title="How can I help you today?"
                description="Ask me about your data, habits, or routines."
              />
            </div>
          ) : (
            messages.map(msg => {
              const isUser = msg.role === 'user'
              return (
                <div
                  key={msg.id}
                  style={{
                    alignSelf: isUser ? 'flex-end' : 'flex-start',
                    maxWidth: '85%',
                    padding: '12px 16px',
                    borderRadius: '16px',
                    background: isUser ? 'var(--accent-indigo)' : 'var(--bg-secondary)',
                    color: isUser ? '#fff' : 'var(--text-1)',
                    borderBottomRightRadius: isUser ? '4px' : '16px',
                    borderBottomLeftRadius: isUser ? '16px' : '4px',
                    lineHeight: '1.5',
