  return (
    <Page title="Money" className="pb-24 max-md:pb-24">
      <Tabs tabs={TABS} value={activeTab} onChange={setActiveTab} />
      
      <AnimatePresence mode="wait">
        <motion.div
          key={activeTab}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
