                  </div>
                </div>
                <div className="font-semibold">
                  Γé╣{Number(exp.amount).toLocaleString('en-IN')}
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

import { useMemo, useState } from 'react'
import { CheckSquare, Plus, Check } from 'lucide-react'
import { Page, Card, StatCard, Button, HeatCalendar, DateNavigator } from '../ui/index'
import { useAppActions, useAppState } from '../context/appHooks'
import { getTodayDateKey, shiftMonth } from '../utils/dateTime'

export default function Habits() {
  const state = useAppState()
  const { updateModule } = useAppActions()
  const today = getTodayDateKey(state.settings?.profile?.timezone)
  const [date, setDate] = useState(today)
  const [viewMonth, setViewMonth] = useState(today.slice(0, 7))

  const routines = (state.habits?.checkpoints || []).filter(r => r.isActive !== false)
  const logs = state.habits?.dailyLogs || []

  const doneToday = id => logs.some(l => l.checkpointId === id && l.date === date && l.status === 'done')

  function toggle(id) {
    if (date > today) return
    updateModule('habits', prev => {
      const isDone = doneToday(id)
      const filtered = (prev.dailyLogs || []).filter(l => !(l.checkpointId === id && l.date === date))
      if (!isDone) {
        filtered.push({ id: crypto.randomUUID(), checkpointId: id, date, status: 'done', loggedAt: new Date().toISOString() })
      }
      return { ...prev, dailyLogs: filtered }
    })
  }

  const getDayCompletion = (d) => {
    if (routines.length === 0) return { value: 0, cellBg: 'transparent' }
    const completed = routines.filter(r => logs.some(l => l.checkpointId === r.id && l.date === d && l.status === 'done')).length
    const ratio = completed / routines.length
    if (ratio === 0) return { value: 0, cellBg: 'transparent' }
    return { value: ratio, cellBg: `rgba(99, 102, 241, ${ratio})`, status: d > today ? 'future' : '' }
  }

  return <Page title="Routines" icon={CheckSquare} color="#6366F1"
    actions={<>
      <DateNavigator value={date} onChange={setDate} today={today} />
      <Button variant="primary" icon={Plus} onClick={() => alert("Add habit not implemented")}>Add</Button>
    </>}>

    <div className="ui-grid cols-2">
      <StatCard label="Active routines" value={routines.length} />
      <StatCard label="Completed today" value={routines.filter(r => doneToday(r.id)).length} />
    </div>

    <Card title="Today's Routines">
      {routines.length === 0 ? <p style={{ color: 'var(--text-3)' }}>No active routines.</p> : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {routines.map(r => (
            <div key={r.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: 12, background: 'var(--card-hover)', borderRadius: 'var(--radius-m)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{ fontSize: 24 }}>{r.icon || '≡ƒÄ»'}</div>
                <div style={{ fontWeight: 600 }}>{r.name || r.title}</div>
              </div>
              <Button variant={doneToday(r.id) ? 'primary' : 'secondary'} icon={Check} onClick={() => toggle(r.id)} disabled={date > today}>
                {doneToday(r.id) ? 'Done' : 'Mark done'}
              </Button>
            </div>
          ))}
        </div>
      )}
    </Card>

    <Card title="Completion Heatmap">
      <HeatCalendar month={viewMonth} getDay={getDayCompletion} />
    </Card>

  </Page>
}

import React, { useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'motion/react';
import { Clock, IndianRupee, Moon, Plus, Target, CheckCircle2, ChevronRight, Zap } from 'lucide-react';
import { Page, Card, StatCard, Button, Ring, EmptyState } from '../ui/index';
import { useLiveNow, useMediaQuery } from '../ui/hooks';
import { fmtMinutes, fmtDate, greeting, fmtClock } from '../ui/format';
import { localDate } from '../domain/metrics/dates';
import { useAppState } from '../context/appHooks';
import { computeDaySync } from '../domain/planning/sync';
import { compactMoney, spendOf } from '../domain/finance';

export default function Home() {
  const navigate = useNavigate();
  const state = useAppState();
  const today = localDate();
  const now = useLiveNow();

  const expenses = state.finance?.expenses || [];
  const timeflow = state.timeflow?.entries || [];
  const planning = state.planning || { drafts: {}, checkins: {} };
  const sleepLogs = state.health?.sleepLogs || [];

  const todayExpenses = expenses.filter(e => e.date === today);
  const spentToday = todayExpenses.length > 0 ? spendOf(todayExpenses) : null;

  const todayTime = timeflow.filter(t => (t.startAt || '').startsWith(today));
  const focusTime = todayTime.filter(t => t.category === 'Focus' || t.bucket === 'Focus').reduce((acc, t) => {
    if (t.duration) return acc + t.duration;
    if (t.startAt && t.endAt) {
      const s = new Date(t.startAt).getTime();
      const e = new Date(t.endAt).getTime();
      return acc + (e - s) / 60000;
    }
    return acc;
  }, 0);

  const lastSleep = sleepLogs.find(s => s.date === today) || sleepLogs[sleepLogs.length - 1];

  const syncResult = useMemo(() => {
    try {
      return computeDaySync(today, planning, timeflow, now);
    } catch (e) {
      return { score: null, maxScore: null, currentBlock: null, pendingCheckins: [] };
    }
  }, [today, planning, timeflow, now]);

  const score = syncResult?.score ?? syncResult?.value ?? null;
  const maxScore = syncResult?.maxScore ?? syncResult?.upper ?? 100;
  const currentBlock = syncResult?.currentBlock;
  const pendingCheckins = syncResult?.pendingCheckins || [];

  return (
    <Page className="ui-page max-w-4xl mx-auto">
      {/* Hero */}
      <div className="relative overflow-hidden rounded-none bg-slate-900 p-8 mb-6 border border-slate-800 shadow-none">
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
           <motion.div 
             animate={{ x: [0, 20, 0], y: [0, -20, 0], opacity: [0.3, 0.5, 0.3] }}
             transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
             className="absolute -top-20 -left-20 w-64 h-64 bg-indigo-500/20 rounded-none blur-3xl"
           />
