import { useState, useMemo } from 'react'
import { v4 as uuid } from 'uuid'
import { NotebookPen, Plus, Trash2, Calendar } from 'lucide-react'
import { Page, Card, Button, Tabs, EmptyState, Field, HeatCalendar, Sheet, Chips } from '../ui/index'
import { useAppState, useAppActions } from '../context/appHooks'
import { getTodayDateKey } from '../utils/dateTime'
import { ResponsiveContainer, LineChart, Line, XAxis, YAxis, Tooltip as RechartsTooltip, CartesianGrid } from 'recharts'

const MOODS = [
  { key: 1, emoji: '≡ƒÿ₧', label: 'Very Low', color: '#EF4444' },
  { key: 2, emoji: '≡ƒÿò', label: 'Low', color: '#F97316' },
  { key: 3, emoji: '≡ƒÿÉ', label: 'Neutral', color: '#F59E0B' },
  { key: 4, emoji: '≡ƒÖé', label: 'Good', color: '#10B981' },
  { key: 5, emoji: '≡ƒÿä', label: 'Great', color: '#3B82F6' },
]

export default function Journal() {
  const state = useAppState()
  const { setModule } = useAppActions()
  const timezone = state.settings?.profile?.timezone
  const today = getTodayDateKey(timezone)

  const entries = state.journal?.entries || []
  const [activeTab, setActiveTab] = useState('entries')
  const [month, setMonth] = useState(today.slice(0, 7))

  const [showComposer, setShowComposer] = useState(false)
  const [text, setText] = useState('')
  const [mood, setMood] = useState(4)

  const sortedEntries = useMemo(() => {
    return [...entries].sort((a, b) => b.date.localeCompare(a.date) || (b.createdAt || '').localeCompare(a.createdAt || ''))
  }, [entries])

  function saveEntry() {
    if (!text.trim()) return
    const newEntry = {
      id: uuid(),
      date: today,
      text: text.trim(),
      mood,
      tags: [],
      createdAt: new Date().toISOString()
    }
    setModule('journal', {
      ...state.journal,
      entries: [newEntry, ...entries]
    })
    setText('')
    setMood(4)
    setShowComposer(false)
  }

  function deleteEntry(id) {
    if (!window.confirm('Delete this entry?')) return
    setModule('journal', {
      ...state.journal,
      entries: entries.filter(e => e.id !== id)
    })
  }

  return (
    <Page 
      title="Journal" 
      icon={NotebookPen} 
      color="#8B5CF6"
      actions={<Button variant="primary" icon={Plus} onClick={() => setShowComposer(true)}>New Entry</Button>}
    >
      <Tabs
        value={activeTab}
        onChange={setActiveTab}
        tabs={[
          { key: 'entries', label: 'Entries', icon: NotebookPen, badge: entries.length },
          { key: 'calendar', label: 'Calendar', icon: Calendar }
        ]}
      />

      <div style={{ marginTop: '1.5rem', display: 'flex', flexDirection: 'column', gap: '1rem' }}>
        {activeTab === 'entries' && (
          sortedEntries.length === 0 ? (
            <EmptyState 
              icon="≡ƒôô" 
              title="No journal entries yet" 
              text="Start reflecting on your days." 
              action={<Button onClick={() => setShowComposer(true)}>Write Entry</Button>} 
            />
          ) : (
            sortedEntries.map(entry => {
              const m = MOODS.find(x => x.key === entry.mood) || MOODS[2]
              const content = entry.text || entry.content || ''
              return (
                <Card key={entry.id}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.75rem' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                      <span style={{ fontSize: '0.9rem', fontWeight: 600, color: 'var(--text-1)' }}>{entry.date}</span>
                      <span style={{ fontSize: '0.75rem', padding: '0.2rem 0.6rem', borderRadius: '0', background: `color-mix(in srgb, ${m.color} 15%, transparent)`, color: m.color, fontWeight: 600 }}>
                        {m.emoji} {m.label}
                      </span>
                    </div>
                    <button 
                      type="button" 
                      className="ui-btn ghost icon sm" 
                      onClick={() => deleteEntry(entry.id)} 
                      aria-label="Delete"
                    >
                      <Trash2 size={16} style={{ color: 'var(--danger-ink)' }} />
                    </button>
                  </div>
                  
                  <div style={{ whiteSpace: 'pre-wrap', color: 'var(--text-1)', fontSize: '0.95rem', lineHeight: 1.6 }}>
                    {content}
                  </div>
                  
                  {entry.tags?.length > 0 && (
                    <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap', marginTop: '1rem' }}>
                      {entry.tags.map(t => (
                        <span key={t} style={{ fontSize: '0.75rem', padding: '0.15rem 0.5rem', borderRadius: '0', background: 'var(--bg-3)', color: 'var(--text-2)' }}>
                          #{t}
                        </span>
                      ))}
                    </div>
                  )}
                </Card>
              )
            })
          )
        )}

        {activeTab === 'calendar' && (
          <Card>
            <HeatCalendar
              month={month}
              onMonthChange={setMonth}
              title="Mood Calendar"
              today={today}
              getDay={(d) => {
                const dayEntries = entries.filter(e => e.date === d)
                if (!dayEntries.length) return { status: 'unknown' }
                const avgMood = Math.round(dayEntries.reduce((a, e) => a + (e.mood || 3), 0) / dayEntries.length)
                const m = MOODS.find(x => x.key === avgMood) || MOODS[2]
                return {
                  status: 'value',
                  value: String(avgMood),
                  cellBg: m.color,
                  ink: '#fff',
                  aria: `Mood: ${m.label}`
                }
              }}
            />
          </Card>
        )}
      </div>

      <Sheet 
        open={showComposer} 
        onClose={() => setShowComposer(false)} 
        title="New Journal Entry"
        footer={
          <>
            <Button variant="ghost" onClick={() => setShowComposer(false)}>Cancel</Button>
            <Button variant="primary" onClick={saveEntry} disabled={!text.trim()}>Save Entry</Button>
          </>
        }
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          <Field label="How are you feeling?">
            <Chips
              options={MOODS}
              value={mood}
              onChange={setMood}
            />
          </Field>
          <Field label="What's on your mind?">
            <textarea
              className="ui-input"
              rows={8}
              value={text}
              onChange={e => setText(e.target.value)}
              placeholder="Write your thoughts here..."
              style={{ resize: 'vertical', width: '100%', fontFamily: 'inherit' }}
            />
          </Field>
        </div>
      </Sheet>
    
    <Card title="Mood Trends">
      <div style={{ height: 200, width: '100%', marginTop: '1rem' }}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={[{day:'1st', mood:3}, {day:'2nd', mood:4}, {day:'3rd', mood:2}, {day:'4th', mood:5}, {day:'5th', mood:4}]} margin={{ top: 10, right: 10, bottom: 0, left: -20 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
            <XAxis dataKey="day" tick={{ fontSize: 12, fill: 'var(--text-muted)' }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 12, fill: 'var(--text-muted)' }} axisLine={false} tickLine={false} domain={[1, 5]} ticks={[1,2,3,4,5]} />
            <RechartsTooltip contentStyle={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: '0' }} />
            <Line type="monotone" dataKey="mood" stroke="#10B981" strokeWidth={3} dot={{ r: 4, fill: '#10B981', strokeWidth: 2, stroke: 'var(--bg-card)' }} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </Card>
  
  </Page>
  )
}

import { useMemo, useState, useCallback } from 'react'
import { motion, AnimatePresence } from 'motion/react'
import { CalendarDays, Edit3, Check, AlertTriangle, Clock, Sparkles, ArrowRight, ChevronDown } from 'lucide-react'
import { Page, Card, StatCard, Tabs, Button, Sheet, EmptyState, Ring, Chips, Confetti, Status } from '../ui/index'
import DateNavigator from '../ui/calendar/DateNavigator'
import HeatCalendar from '../ui/calendar/HeatCalendar'
import { heatColor, syncColor } from '../ui/calendar/calendarMath'
import { useLocalPref, useLiveNow } from '../ui/hooks'
import { fmtMinutes, fmtClock, fmtPct, fmtDate, relativeDay } from '../ui/format'
import { localDate, addDays } from '../domain/metrics/dates'
import { parseDiary, resolveAmbiguity, scheduleDraft } from '../domain/planning'
import { computeDaySync, burnUpSeries } from '../domain/planning/sync'
import { useAppState, useAppActions } from '../context/appHooks'
import { useNavigate, useSearchParams } from 'react-router-dom'

const PRIORITY_COLORS = { must: '#F43F5E', should: '#F59E0B', could: '#22D3EE' }

export default function Plan() {
  const state = useAppState()
  const { updateModule, patchModule } = useAppActions()
  const navigate = useNavigate()
  const [params] = useSearchParams()
  const now = useLiveNow(60000)
  const today = localDate(now)
  const [date, setDate] = useState(params.get('date') || today)
  const [view, setView] = useLocalPref('plan_view', 'day')
  const [showCompose, setShowCompose] = useState(false)
  const [diaryText, setDiaryText] = useState('')
  const [confetti, setConfetti] = useState(false)

  const draft = state.planning?.drafts?.[date]
  const approved = draft?.status === 'approved'
  const blocks = draft?.blocks || []

  // Parse diary text
  const parsed = useMemo(() => {
    if (!diaryText.trim()) return null
    try { return parseDiary(diaryText) } catch { return null }
  }, [diaryText])

  // Compute sync for this day
  const sync = useMemo(() => {
    try { return computeDaySync(state, date, { now, timezone: 'Asia/Kolkata', mode: 'live' }) }
    catch { return null }
  }, [state, date, now])

  const views = [
    { key: 'day', label: 'Day' },
    { key: 'compare', label: 'Compare' },
    { key: 'month', label: 'Month' },
  ]

  const handleSaveDraft = useCallback(() => {
    if (!parsed?.length) return
    const scheduled = scheduleDraft(parsed, { localDate: date, timezone: 'Asia/Kolkata' })
    patchModule('planning', { drafts: { ...state.planning?.drafts, [date]: { blocks: scheduled.blocks, unscheduled: scheduled.unscheduled, status: 'draft', createdAt: new Date().toISOString() } } })
    setDiaryText('')
    setShowCompose(false)
  }, [parsed, date, patchModule, state.planning?.drafts])

  const handleApprove = useCallback(async () => {
    if (!draft) return
    patchModule('planning', { drafts: { ...state.planning?.drafts, [date]: { ...draft, status: 'approved', approvedAt: new Date().toISOString() } } })
    setConfetti(true)
    try {
      const { exportApprovedPlan } = await import('../services/calendarService')
      await exportApprovedPlan(draft)
    } catch (err) {
      console.warn('Failed to sync to Google Calendar:', err)
    }
  }, [draft, date, patchModule, state.planning?.drafts])

  return <Page title="Plan" icon={CalendarDays} color="#6366F1"
    actions={<>
      <DateNavigator value={date} onChange={setDate} today={today} max={addDays(today, 7)} />
      <Button variant="primary" icon={Edit3} onClick={() => setShowCompose(true)}>Write plan</Button>
    </>}>

    <Confetti fire={confetti} onDone={() => setConfetti(false)} />

    <Tabs tabs={views} value={view} onChange={setView} id="plan" />

    {/* Sync summary strip */}
    {sync && sync.status !== 'no-plan' && <div className="ui-grid cols-3">
      <StatCard label="Sync" value={sync.timing?.value} format={v => fmtPct(v)} color={syncColor(sync.timing?.value)} icon={Sparkles}
        truth={{ status: sync.timing?.value >= .8 ? 'complete' : sync.timing?.value >= .5 ? 'partial' : 'low',
          rows: [['Timing', fmtPct(sync.timing?.value)], ['Effort', fmtPct(sync.effort?.value)], ['Outcome', fmtPct(sync.outcome?.value)]],
          note: `${sync.details?.filter(d => d.status === 'on-time' || d.status === 'done-untimed').length || 0} of ${sync.details?.length || 0} blocks on track`
        }} />
      <StatCard label="Must" value={sync.must?.completed != null ? sync.must.completed : null} format={v => `${v}/${sync.must?.total || 0}`} color="#F43F5E" />
      <StatCard label="Status" value={null} note={sync.status === 'complete' ? 'Γ£ô Day complete' : sync.status === 'partial' ? 'In progress' : 'Not started'} />
    </div>}

    {view === 'day' && <DayView date={date} blocks={blocks} draft={draft} approved={approved} sync={sync} onApprove={handleApprove} navigate={navigate} />}
    {view === 'compare' && <CompareView date={date} sync={sync} blocks={blocks} />}
    {view === 'month' && <MonthView state={state} date={date} setDate={setDate} today={today} now={now} />}

    {/* Diary composer sheet */}
    <Sheet open={showCompose} onClose={() => setShowCompose(false)} title={`Plan for ${relativeDay(date, today)}`}
      footer={<><Button variant="ghost" onClick={() => setShowCompose(false)}>Cancel</Button><Button variant="primary" onClick={handleSaveDraft} disabled={!parsed?.length}>Save draft</Button></>}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
        <p style={{ fontSize: '.82rem', color: 'var(--text-3)' }}>Write what you want to do today in your own words (Hindi/English). LifeOS will parse it into a timeline.</p>
        <textarea className="ui-input" rows={8} value={diaryText} onChange={e => setDiaryText(e.target.value)}
          placeholder={"subah 7 baje uthna\n8-9 study maths\n10 se 12 coding project\nlunch 1 bje\ndopahar gym 1 hour\nshaam reading 2 ghante\nraat 10 bje sona"} style={{ fontFamily: 'var(--font-sans)', lineHeight: 1.6 }} />
        {parsed && <Card eyebrow="Preview" title={`${parsed.length} tasks parsed`}>
          <div className="ui-list">
            {parsed.map((t, i) => <div key={i} className="ui-row">
              <span style={{ width: 8, height: 8, borderRadius: '0', background: PRIORITY_COLORS[t.priority] || '#94A3B8', flexShrink: 0 }} />
              <div className="grow">
                <div className="title">{t.title}</div>
                <div className="meta">
                  {t.startTime && fmtClock(t.startTime)}{t.startTime && t.endTime && ' ΓÇô '}{t.endTime && fmtClock(t.endTime)}
                  {t.estimateMinutes && ` ┬╖ ${fmtMinutes(t.estimateMinutes)}`}
                  {t.warning && <span style={{ color: 'var(--warning-ink)' }}> ΓÜá {t.warning}</span>}
                </div>
              </div>
              <span style={{ fontSize: '.68rem', fontWeight: 700, color: PRIORITY_COLORS[t.priority] || 'var(--text-3)', textTransform: 'uppercase' }}>{t.priority}</span>
            </div>)}
          </div>
          {parsed.some(t => t.ambiguity) && <Status tone="warn" style={{ marginTop: 12 }}>Some times are ambiguous ΓÇö review after saving.</Status>}
        </Card>}
      </div>
    </Sheet>
    <div className="pb-24 h-24 min-h-[6rem] mb-12"></div>
    </Page>
}

function DayView({ date, blocks, draft, approved, sync, onApprove, navigate }) {
  if (!draft || blocks.length === 0) {
    return <EmptyState emoji="≡ƒô¥" title="No plan yet" text={`Write what you want to do ${relativeDay(date, localDate()) === 'Today' ? 'today' : 'on ' + fmtDate(date, 'weekday')}`}
      action={<Button variant="primary" icon={Edit3} onClick={() => navigate(`/plan?date=${date}`)}>Write plan</Button>} />
  }

  return <Card>
    {!approved && <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
      <Status tone="warn">Draft ΓÇö review and approve to push to calendar</Status>
      <Button variant="success" icon={Check} onClick={onApprove}>Approve</Button>
    </div>}

    <div className="ui-list">
      {blocks.map((block, i) => {
        const detail = sync?.details?.find(d => d.blockId === block.id)
        const statusColor = detail?.status === 'on-time' ? '#10B981' : detail?.status === 'late' || detail?.status === 'shifted' ? '#F59E0B' : detail?.status === 'skipped' || detail?.status === 'missed' ? '#F43F5E' : 'var(--text-3)'
        return <div key={block.id || i} className="ui-row" style={{ borderLeft: `3px solid ${PRIORITY_COLORS[block.priority] || '#94A3B8'}` }}>
          <div style={{ width: 50, textAlign: 'center', fontSize: '.72rem', fontWeight: 700, color: 'var(--text-3)' }}>
            {block.startTime && fmtClock(block.startTime)}
          </div>
          <div className="grow">
            <div className="title">{block.title}</div>
            <div className="meta">
              {block.estimateMinutes && fmtMinutes(block.estimateMinutes)}
              {detail?.status && <span style={{ color: statusColor, marginLeft: 8 }}>
                {detail.status === 'on-time' ? 'Γ£ô On time' : detail.status === 'late' ? 'ΓÅ▒ Late' : detail.status === 'shifted' ? 'Γå¬ Shifted' : detail.status === 'skipped' ? 'Γ£ù Skipped' : detail.status === 'missed' ? 'Γ£ù Missed' : detail.status}
              </span>}
            </div>
          </div>
          <span style={{ fontSize: '.68rem', fontWeight: 700, color: PRIORITY_COLORS[block.priority] || 'var(--text-3)', textTransform: 'uppercase' }}>{block.priority}</span>
        </div>
      })}
    </div>
  </Card>
}

function CompareView({ date, sync, blocks }) {
  if (!sync || sync.status === 'no-plan') {
    return <EmptyState emoji="≡ƒöä" title="Nothing to compare" text="Approve a plan and log some activities to see how your day unfolded vs what you planned." />
  }

  return <>
    {/* Sync ring */}
    <Card>
      <div style={{ display: 'flex', alignItems: 'center', gap: 24, justifyContent: 'center', padding: '1rem 0' }}>
        <Ring value={sync.timing?.value} upper={sync.timing?.upper} size={140} stroke={12} color={syncColor(sync.timing?.value) || 'var(--accent)'}>
          <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 800, fontSize: '1.4rem' }}>{fmtPct(sync.timing?.value)}</div>
          <div style={{ fontSize: '.68rem', color: 'var(--text-3)' }}>Sync</div>
        </Ring>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
          <div><span style={{ fontWeight: 700, color: 'var(--text-3)', fontSize: '.72rem', textTransform: 'uppercase' }}>Timing</span> {fmtPct(sync.timing?.value)}</div>
          <div><span style={{ fontWeight: 700, color: 'var(--text-3)', fontSize: '.72rem', textTransform: 'uppercase' }}>Effort</span> {fmtPct(sync.effort?.value)}</div>
          <div><span style={{ fontWeight: 700, color: 'var(--text-3)', fontSize: '.72rem', textTransform: 'uppercase' }}>Outcome</span> {fmtPct(sync.outcome?.value)}</div>
          {sync.startDelay && <div><span style={{ fontWeight: 700, color: 'var(--text-3)', fontSize: '.72rem', textTransform: 'uppercase' }}>Start delay</span> {fmtMinutes(sync.startDelay.median)}</div>}
        </div>
      </div>
    </Card>

    {/* Dual timeline */}
    {sync.details?.length > 0 && <Card title="Planned vs Actual">
      <div className="ui-list">
        {sync.details.map((d, i) => {
          const block = blocks.find(b => b.id === d.blockId) || {}
          const statusIcon = d.status === 'on-time' ? 'Γ£ô' : d.status === 'late' || d.status === 'shifted' ? 'ΓÅ▒' : d.status === 'skipped' || d.status === 'missed' ? 'Γ£ù' : 'ΓùÉ'
          const statusColor = d.status === 'on-time' ? '#10B981' : d.status === 'late' || d.status === 'shifted' ? '#F59E0B' : d.status === 'skipped' || d.status === 'missed' ? '#F43F5E' : 'var(--text-3)'
          return <div key={d.blockId || i} className="ui-row">
            <div style={{ width: 28, height: 28, borderRadius: 8, background: `color-mix(in srgb, ${statusColor} 18%, transparent)`, display: 'grid', placeItems: 'center', color: statusColor, fontWeight: 800, fontSize: '.82rem', flexShrink: 0 }}>{statusIcon}</div>
            <div className="grow">
              <div className="title">{block.title || d.blockId}</div>
              <div className="meta">
                {d.status}{d.derailReason ? ` ΓÇö ${d.derailReason}` : ''}
                {d.actualSpans?.length > 0 && ` ┬╖ Actually: ${d.actualSpans.map(s => fmtMinutes(s.minutes)).join(', ')}`}
              </div>
            </div>
            <div className="amt" style={{ color: statusColor }}>{d.blockFit != null ? fmtPct(d.blockFit) : ''}</div>
          </div>
        })}
      </div>
    </Card>}

    {/* Derails */}
    {sync.derails?.length > 0 && <Card title="Derails" eyebrow={`${sync.derails.length} moments`}>
      <div className="ui-list">
        {sync.derails.map((d, i) => <div key={i} className="ui-row" style={{ borderLeft: '3px solid #F43F5E' }}>
          <div className="grow">
            <div className="title">{d.reason || 'Deviation from plan'}</div>
            <div className="meta">{d.planned && `Planned: ${d.planned}`}{d.actual && ` ΓåÆ Actual: ${d.actual}`}</div>
          </div>
        </div>)}
      </div>
    </Card>}
  </>
}

function MonthView({ state, date, setDate, today, now }) {
  const month = date.slice(0, 7)
  const [selected, setSelected] = useState(null)

  const getDay = d => {
    if (d > today) return { status: 'future' }
    const draft = state.planning?.drafts?.[d]
    if (!draft) return { status: 'unknown' }
    let sync
    try { sync = computeDaySync(state, d, { now, timezone: 'Asia/Kolkata', mode: 'final' }) } catch { return { status: 'value', value: '≡ƒô¥' } }
    const v = sync.timing?.value
    return {
      status: 'value', value: v != null ? fmtPct(v) : '≡ƒô¥',
      cellBg: v != null ? heatColor(syncColor(v)?.replace('#', '') || '6366F1', v) : undefined,
      badges: draft.status === 'approved' ? ['Γ£ô'] : [],
    }
  }

  return <HeatCalendar month={month} onMonthChange={m => setDate(`${m}-01`)} getDay={getDay}
    selected={selected} onSelect={d => { setSelected(d); setDate(d) }} today={today} maxMonth={today.slice(0, 7)} />
}

import { useMemo, useState } from 'react'
import { motion, AnimatePresence } from 'motion/react'
import { Clock, Plus, Zap, Coffee, Moon, Sunrise, Sun as SunIcon, Sunset } from 'lucide-react'
import { Page, Card, StatCard, Tabs, Button, Chips, EmptyState, Sheet, Ring, Legend } from '../ui/index'
import HeatCalendar from '../ui/calendar/HeatCalendar'
import DateNavigator from '../ui/calendar/DateNavigator'
import { heatColor } from '../ui/calendar/calendarMath'
import { useLocalPref, useLiveNow } from '../ui/hooks'
import { fmtMinutes, fmtHours, fmtClock, fmtDate } from '../ui/format'
import { localDate, dayBounds, addDays } from '../domain/metrics/dates'
import { adaptActivities, resolveSegments, classifyActivity, ALLOCATION_BUCKETS } from '../domain/metrics/records'
import { useAppState, useAppActions } from '../context/appHooks'
import { useNavigate } from 'react-router-dom'

const BUCKET_COLORS = { Focus: '#6366F1', Health: '#10B981', Essentials: '#94A3B8', Leisure: '#F59E0B', Drift: '#F43F5E', Sleep: '#818CF8', Other: '#64748B', Conflict: '#EF4444' }
const THEME = hour => {
  if (hour < 6) return { label: 'Night', icon: Moon, bg: '#111', orb: '#6366F1' }
  if (hour < 12) return { label: 'Morning', icon: Sunrise, bg: '#111', orb: '#F59E0B' }
  if (hour < 17) return { label: 'Afternoon', icon: SunIcon, bg: '#111', orb: '#22D3EE' }
  if (hour < 21) return { label: 'Evening', icon: Sunset, bg: '#111', orb: '#A78BFA' }
  return { label: 'Night', icon: Moon, bg: '#111', orb: '#6366F1' }
}

export default function TimeFlow() {
  const state = useAppState()
  const navigate = useNavigate()
  const now = useLiveNow(30000)
  const today = localDate(now)
  const [date, setDate] = useState(today)
  const [tab, setTab] = useLocalPref('timeflow_tab', 'day')
  const hour = new Date(now).getHours()
  const theme = THEME(hour)

  const { records, repair } = useMemo(() => adaptActivities(state), [state])
  const dayRecords = useMemo(() => records.filter(r => r.date === date), [records, date])
  const bounds = useMemo(() => { try { return dayBounds(date, 'Asia/Kolkata', now) } catch { return null } }, [date, now])
  const segments = useMemo(() => bounds ? resolveSegments(dayRecords, bounds.start, bounds.cutoff) : [], [dayRecords, bounds])

  const bucketMinutes = useMemo(() => {
    const m = {}; ALLOCATION_BUCKETS.forEach(b => { m[b] = 0 })
    segments.forEach(s => { m[s.bucket] = (m[s.bucket] || 0) + s.minutes })
    return m
  }, [segments])
  const totalLogged = Object.values(bucketMinutes).reduce((a, b) => a + b, 0)
  const gapMinutes = bounds ? bounds.elapsedMinutes - totalLogged : 0

  const tabs = [
    { key: 'day', label: 'Day' },
    { key: 'week', label: 'Week' },
    { key: 'month', label: 'Month' },
  ]

  return <Page title="Time Flow" icon={Clock} color="#22D3EE" className="pb-24 max-md:pb-24"
    actions={<>
      <DateNavigator value={date} onChange={setDate} today={today} max={today} />
      <Button variant="primary" icon={Plus} onClick={() => navigate('/capture?type=time')}>Log</Button>
    </>}>

    {/* Live clock hero */}
    {date === today && <Card glass style={{ background: theme.bg, position: 'relative', overflow: 'hidden', padding: '2rem 1.5rem', borderRadius: '0', boxShadow: 'none' }}>
      <div className="orb" style={{ '--orb': theme.orb, top: '-30%', right: '-10%', width: 300, height: 300, opacity: .35, filter: 'blur(50px)' }} />
      <div style={{ position: 'relative', zIndex: 1, display: 'flex', alignItems: 'center', gap: 16 }}>
        <div>
          <div style={{ fontSize: '.8rem', textTransform: 'uppercase', letterSpacing: '.15em', fontWeight: 700, color: 'rgba(255,255,255,.7)', display: 'flex', alignItems: 'center', gap: 6 }}>
            <theme.icon size={16} />{theme.label}
          </div>
          <div style={{ fontFamily: 'var(--font-mono)', fontWeight: 800, fontSize: 'clamp(2.5rem, 6vw, 4rem)', lineHeight: 1.1, color: '#FFFFFF', letterSpacing: '-0.02em', marginTop: '4px', textShadow: 'none' }}>
            {new Date(now).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })}
          </div>
          <div style={{ fontSize: '1rem', color: 'rgba(255,255,255,.6)', marginTop: 8, fontWeight: 500 }}>{fmtDate(today, 'long')}</div>
        </div>
      </div>
    </Card>}

    <Tabs tabs={tabs} value={tab} onChange={setTab} id="tf" />

    {tab === 'day' && <DayView date={date} segments={segments} bucketMinutes={bucketMinutes} totalLogged={totalLogged} gapMinutes={gapMinutes} dayRecords={dayRecords} bounds={bounds} navigate={navigate} />}
    {tab === 'week' && <WeekView records={records} date={date} today={today} now={now} />}
    {tab === 'month' && <MonthView records={records} date={date} setDate={setDate} today={today} now={now} />}
    <div className="pb-24 h-24 min-h-[6rem] mb-12"></div>
    </Page>
}

import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RechartsTooltip, LineChart, Line, XAxis, YAxis } from 'recharts'

function DayView({ date, segments, bucketMinutes, totalLogged, gapMinutes, dayRecords, bounds, navigate }) {
  const active = ALLOCATION_BUCKETS.filter(b => bucketMinutes[b] > 0)
  
  const pieData = active.map(b => ({ name: b, value: bucketMinutes[b] }))
  if (gapMinutes > 15) pieData.push({ name: 'Unlogged', value: gapMinutes })

  return <>
    {/* Stats strip */}
    <div className="ui-grid cols-4">
      <StatCard label="Logged" value={totalLogged > 0 ? totalLogged : null} format={v => fmtMinutes(v)} color="#22D3EE"
        placeholder={{ label: '+ Log', onClick: () => navigate('/capture?type=time') }} />
      <StatCard label="Focus" value={bucketMinutes.Focus > 0 ? bucketMinutes.Focus : null} format={v => fmtHours(v)} color="#6366F1" />
      <StatCard label="Unlogged" value={gapMinutes > 5 ? gapMinutes : null} format={v => fmtMinutes(v)} color="#64748B" />
      <StatCard label="Drift" value={bucketMinutes.Drift > 0 ? bucketMinutes.Drift : null} format={v => fmtMinutes(v)} color="#F43F5E" />
    </div>

    {/* Distribution Chart */}
    {(totalLogged > 0 || gapMinutes > 60) && (
      <Card title="Time Distribution">
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
          <div style={{ height: 160, width: 160, flexShrink: 0 }}>
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={pieData} cx="50%" cy="50%" innerRadius={45} outerRadius={70} dataKey="value" paddingAngle={3} animationDuration={1000}>
                  {pieData.map((entry, i) => (
                    <Cell key={i} fill={entry.name === 'Unlogged' ? 'rgba(100,116,139,0.3)' : BUCKET_COLORS[entry.name]} />
                  ))}
                </Pie>
                <RechartsTooltip formatter={(v) => fmtMinutes(v)} contentStyle={{ background: '#1E293B', border: 'none', borderRadius: 0, color: '#F8FAFC' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignContent: 'center' }}>
            {active.map(b => <span key={b} style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '.3rem .7rem', borderRadius: 0,
              background: `color-mix(in srgb, ${BUCKET_COLORS[b]} 15%, transparent)`, border: `1px solid color-mix(in srgb, ${BUCKET_COLORS[b]} 35%, transparent)`,
              fontSize: '.78rem', fontWeight: 650 }}>
              <i style={{ width: 8, height: 8, borderRadius: '0', background: BUCKET_COLORS[b], display: 'inline-block' }} />
              {b} ┬╖ {fmtMinutes(bucketMinutes[b])}
            </span>)}
            {gapMinutes > 15 && <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '.3rem .7rem', borderRadius: 0, background: 'rgba(100,116,139,0.1)', border: '1px solid rgba(100,116,139,0.2)', fontSize: '.78rem', fontWeight: 650, color: '#94A3B8' }}>Unlogged ┬╖ {fmtMinutes(gapMinutes)}</span>}
          </div>
        </div>
      </Card>
    )}

    {/* Timeline */}
    <Card title="Timeline">
      {segments.length === 0 ? <EmptyState emoji="ΓÅ▒" title="No entries yet" text="Log your first activity to see the timeline" action={<Button icon={Plus} onClick={() => navigate('/capture?type=time')}>Log time</Button>} />
        : <div className="ui-list">
          {segments.map((seg, i) => {
            const color = BUCKET_COLORS[seg.bucket] || '#64748B'
            return <div key={i} className="ui-row" style={{ borderLeft: `3px solid ${color}` }}>
              <div style={{ width: 44, textAlign: 'center', fontSize: '.72rem', fontWeight: 700, color: 'var(--text-3)' }}>
                {fmtClock(new Date(seg.startAt).toTimeString().slice(0, 5))}
              </div>
              <div className="grow">
                <div className="title">{seg.bucket}{seg.isStudy ? ' ┬╖ Study' : ''}</div>
                <div className="meta">{fmtClock(new Date(seg.startAt).toTimeString().slice(0, 5))} ΓÇô {fmtClock(new Date(seg.endAt).toTimeString().slice(0, 5))} ┬╖ {fmtMinutes(seg.minutes)}</div>
              </div>
              <div className="amt" style={{ color }}>{fmtMinutes(seg.minutes)}</div>
            </div>
          })}
        </div>}
    </Card>
  </>
}

function WeekView({ records, date, today, now }) {
  const days = Array.from({ length: 7 }, (_, i) => addDays(date, i - 6))
  
  const weeklyData = days.map(d => {
    const dayRecs = records.filter(r => r.date === d)
    const focus = dayRecs.filter(r => r.bucket === 'Focus').reduce((a, r) => a + (r.durationMinutes || 0), 0)
    const total = dayRecs.reduce((a, r) => a + (r.durationMinutes || 0), 0)
    return {
      day: fmtDate(d, 'day').split(' ')[1]?.slice(0, 3) || d.slice(8),
      focus: Number((focus / 60).toFixed(1)),
      other: Number(((total - focus) / 60).toFixed(1)),
      total: Number((total / 60).toFixed(1))
    }
  })

  return (
    <Card title="Productive vs Other (Last 7 Days)">
      <div style={{ height: 220, width: '100%', marginTop: '1rem' }}>
        <ResponsiveContainer width="100%" height="100%">
          <LineChart data={weeklyData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
            <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill: 'var(--text-3)', fontSize: 12}} />
            <YAxis axisLine={false} tickLine={false} tick={{fill: 'var(--text-3)', fontSize: 12}} />
            <RechartsTooltip formatter={(v, name) => [`${v}h`, name]} contentStyle={{ background: '#1E293B', border: 'none', borderRadius: 0, color: '#F8FAFC' }} />
            <Line type="monotone" dataKey="focus" name="Focus" stroke="#6366F1" strokeWidth={3} dot={{ fill: '#6366F1', r: 4 }} activeDot={{ r: 6 }} animationDuration={1500} />
            <Line type="monotone" dataKey="other" name="Other" stroke="#94A3B8" strokeWidth={3} dot={{ fill: '#94A3B8', r: 4 }} activeDot={{ r: 6 }} animationDuration={1500} />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </Card>
  )
}

function MonthView({ records, date, setDate, today, now }) {
  const month = date.slice(0, 7)
  const [selectedDate, setSelectedDate] = useState(null)

  const getDay = d => {
    if (d > today) return { status: 'future' }
    const dayRecs = records.filter(r => r.date === d)
    const total = dayRecs.reduce((a, r) => a + (r.durationMinutes || 0), 0)
    if (dayRecs.length === 0) return { status: 'unknown' }
    const focus = dayRecs.filter(r => r.bucket === 'Focus').reduce((a, r) => a + (r.durationMinutes || 0), 0)
    return {
      status: 'value', value: fmtHours(total),
      cellBg: heatColor('#6366F1', Math.min(1, total / 600)),
      dots: focus > 0 ? ['#6366F1'] : [],
    }
  }

  return <>
    <HeatCalendar month={month} onMonthChange={m => setDate(`${m}-01`)} getDay={getDay}
      selected={selectedDate} onSelect={setSelectedDate} today={today} maxMonth={today.slice(0, 7)}
      legend={<Legend items={[['rgba(99,102,241,.2)', 'Low'], ['rgba(99,102,241,.5)', 'Medium'], ['rgba(99,102,241,.85)', 'High'], ['transparent', 'Not logged']]} />} />
  </>
}

